<template><div v-if="isLoggedIn" class="login-user-wrap"><AvatarIcon :type="user?.avatar||'eye'" :size="90" @click="showDropdown=!showDropdown"/><div v-if="showDropdown" class="user-dropdown"><button class="user-dropdown-item" @click="open('password')">{{t('changePassword')}}</button><button class="user-dropdown-item" @click="open('email')">{{user?.email?t('updateEmail'):t('bindEmail')}}</button><button class="user-dropdown-item" @click="logout();showDropdown=false">{{t('logout')}}</button></div><Teleport to="body"><ChangePasswordModal v-if="modal==='password'" @close="modal=''"/><BindEmailModal v-if="modal==='email'" @close="modal=''"/></Teleport></div><template v-else><button class="login-btn" @click="modal='login'"><span class="login-btn-text">{{t('login')}}</span></button><Teleport to="body"><LoginModal v-if="modal==='login'" @close="modal=''"/></Teleport></template></template>
<script setup>import {ref} from 'vue'; import {useAuth,useLang} from '../contexts/app'; import AvatarIcon from './AvatarIcon.vue'; import LoginModal from './LoginModal.vue'; import ChangePasswordModal from './ChangePasswordModal.vue'; import BindEmailModal from './BindEmailModal.vue'; import './LoginButton.css'; const {user,isLoggedIn,logout}=useAuth();const {t}=useLang();const showDropdown=ref(false),modal=ref('');const open=(x)=>{modal.value=x;showDropdown.value=false};</script>
